CREATE TABLE IF NOT EXISTS market_agent_profiles (id TEXT PRIMARY KEY, owner_subject_hash TEXT NOT NULL UNIQUE, revision INTEGER NOT NULL DEFAULT 1, watchlist_revision TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS market_watchlists (profile_id TEXT NOT NULL, revision TEXT NOT NULL, items_json TEXT NOT NULL, confirmed_at TEXT NOT NULL, PRIMARY KEY(profile_id, revision));
CREATE TABLE IF NOT EXISTS agent_runs (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL, workflow TEXT NOT NULL, trigger TEXT NOT NULL, status TEXT NOT NULL, idempotency_key TEXT NOT NULL, command_hash TEXT NOT NULL, revision_of_run_id TEXT, attempt INTEGER NOT NULL DEFAULT 0, recovery_generation INTEGER NOT NULL DEFAULT 0, lease_owner TEXT, lease_token TEXT, lease_expires_at TEXT, evidence_fingerprint TEXT, failure_json TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(profile_id, idempotency_key));
CREATE TABLE IF NOT EXISTS run_dispatch_outbox (id TEXT PRIMARY KEY, run_id TEXT NOT NULL, generation INTEGER NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL, sent_at TEXT, UNIQUE(run_id, generation));
CREATE TABLE IF NOT EXISTS run_market_snapshots (run_id TEXT PRIMARY KEY, snapshot_json TEXT NOT NULL, fingerprint TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS market_events (id TEXT PRIMARY KEY, run_id TEXT NOT NULL, event_json TEXT NOT NULL, dedupe_key TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS dead_letter_records (id TEXT PRIMARY KEY, run_id TEXT, message_id TEXT NOT NULL UNIQUE, status TEXT NOT NULL, error_code TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_agent_runs_status_lease ON agent_runs(status, lease_expires_at);
